          <el-button v-if="store.isAdmin" @click="editService()" :disabled="busy">添加服务权益</el-button>
        </section>
      </div>
      <section class="panel quote-panel"><div class="section-head"><div><h2>整包报价</h2><p class="muted">人工填写每包价格，留空即未报价；0 元也可明确报价。</p></div><strong>{{ formatBenefitCents(draft.quote.amountCents) }}</strong></div><div class="quote-input"><el-input :model-value="quoteText" :disabled="!store.isAdmin || saving || generating" placeholder="未报价" inputmode="decimal" aria-label="每包报价（元）" data-benefit-quote @update:model-value="updateQuote"><template #prepend>人民币 ¥</template><template #append>元 / 包</template></el-input><el-button v-if="store.isAdmin && validation.quoteNeedsReview && !quoteError" @click="reviewQuote">已复核当前报价</el-button></div><p v-if="quoteError" role="alert" class="issue-error">{{ quoteError }}</p><p v-else-if="validation.quoteNeedsReview" class="issue-warn" data-benefit-quote-review>组成或数量变化后，原报价保留为待复核参考。正式交付需再次核对当前组成和报价。</p></section>
      <section class="panel advanced-panel"><el-collapse v-model="advancedOpen"><el-collapse-item name="rules" title="高级设置 · 选配规则与快充要求"><BenefitRuleEditor :ref="instance => { ruleEditor = instance as InstanceType<typeof BenefitRuleEditor> | undefined }" :issues="validation.issues.filter(issue => issue.groupId)" v-model="draft.groups" v-model:enabled="draft.rulesEnabled" :candidates="allCandidates" :disabled="!store.isAdmin || saving || generating" /><el-divider /><el-checkbox v-model="draft.requireFastCharge" :disabled="!store.isAdmin || saving || generating" data-benefit-require-fast>本包明确要求快充能力</el-checkbox><p class="muted fast-note">默认仅核对基本使用；快充能力按已有独立声明及实际前提校验，不根据商品名称或标称功率推断。</p></el-collapse-item></el-collapse></section>
      <section v-if="validation.issues.length" class="panel issues-panel" data-benefit-issues><h2>待完善与交付提示</h2><ul><li v-for="(issue, index) in validation.issues" :key="`${issue.code}-${index}`" :class="issue.severity === 'error' ? 'issue-error' : 'issue-warn'"><button type="button" class="issue-location" @click="locateIssue(issue)">{{ issue.message }}<span aria-hidden="true"> →</span></button></li></ul><el-button v-if="draft.device" link type="primary" @click="manageCompatibility()">管理适用关系</el-button></section>
      <section v-if="draft.id" class="panel delivery-panel" data-benefit-delivery-generation><div class="section-head"><div><h2>交付清单</h2><p class="muted">保存包配置后，再按本次包数明确生成。历史清单独立保存。</p></div><el-button v-if="store.isAdmin" link :type="draft.status === 'disabled' ? 'primary' : 'danger'" :disabled="(dirty) || busy" @click="setStatus(draft.status === 'disabled' ? 'available' : 'disabled')">{{ draft.status === 'disabled' ? '重新启用' : '停用权益包' }}</el-button></div><div v-if="store.isAdmin" class="delivery-tools"><label>本次包数</label><BenefitIntegerInput v-model="deliveryCount" label="本次包数" controls data-benefit-package-count /><el-button type="primary" plain :disabled="!canGenerate || busy" @click="makeDeliveryPreview" data-benefit-preview-delivery>{{ deliveryPreview ? '重新预览本次交付' : '预览本次交付' }}</el-button><span v-if="!canGenerate" class="muted">{{ dirty ? '请先保存当前编辑' : draft.status !== 'available' ? '可用权益包才可生成新清单' : '请读取最新配置' }}</span></div><div v-if="deliveryPreview" class="delivery-preview" data-benefit-delivery-preview><BenefitDeliverySheet :delivery="deliveryPreview" /><ul v-if="deliveryPreview.issues.length" class="delivery-preview-issues"><li v-for="(issue, index) in deliveryPreview.issues" :key="index" :class="issue.severity === 'warning' ? 'issue-warn' : 'issue-error'">{{ issue.message }}</li></ul><el-checkbox v-model="deliveryConfirmed" :disabled="!deliveryPreview.canConfirm" data-benefit-delivery-confirmation>我已核对本次完整组成、数量、适配前提及报价（含未报价）</el-checkbox><p class="muted">确认后保存这份交付约定；不会进行支付、库存扣减、出库或服务激活。</p><el-button type="primary" :loading="generating" :disabled="!deliveryConfirmed || !deliveryPreview.canConfirm || busy" @click="generate" data-benefit-confirm-delivery>确认生成清单</el-button></div><div class="delivery-history" v-if="relatedDeliveries.length"><h3>已保存清单</h3><button v-for="item in relatedDeliveries" :key="item.id" class="history-item" @click="openDelivery(item.id)"><span>{{ item.code }} · {{ item.packageCount }} 包 · 修订 {{ item.sourceRevision }}</span><span>{{ formatBenefitCents(item.quote.totalCents) }}</span></button></div></section>
      <div class="footer-bar package-actions"><p class="muted">{{ dirty ? '当前更改尚未保存' : draft.id ? '当前配置已保存' : '新建配置尚未保存' }}</p><div class="row-actions"><el-button @click="back" data-benefit-cancel :disabled="busy">取消</el-button><el-button v-if="store.isAdmin" :loading="saving" @click="save('draft')" data-benefit-save-draft :disabled="busy">保存草稿</el-button><el-button v-if="store.isAdmin" :loading="saving" @click="save('available')" data-benefit-save :disabled="busy">保存权益包</el-button><el-button v-if="store.isAdmin" type="primary" :loading="saving" @click="saveAndPreview" data-benefit-save-preview :disabled="busy">保存并预览交付</el-button></div></div>
    </template>
    <BenefitServiceDialog :disabled="busy" :ref="instance => { serviceDialog = instance as InstanceType<typeof BenefitServiceDialog> | undefined }" v-model="serviceOpen" :service="editedService" @save="saveService" @dirty-change="serviceDirty = $event" @request-close="requestServiceClose" />
    <el-dialog v-model="replaceOpen" title="替换具体 SKU" width="min(620px,94vw)" :close-on-click-modal="false"><p class="muted dialog-intro">保留原每包数量，重新核对规则与适配；若目标已在清单中，将按真实 SKU 合并数量。</p><el-select v-model="replaceSkuId" filterable placeholder="选择真实销售 SKU" aria-label="替换 SKU" style="width:100%" data-benefit-replacement><el-option v-for="sku in allCandidates" :key="sku.skuId" :label="`${sku.code} · ${sku.name} · ${sku.spec}`" :value="sku.skuId" /></el-select><template #footer><el-button @click="replaceOpen = false">取消</el-button><el-button type="primary" :disabled="!replaceSkuId" @click="replace">确认替换</el-button></template></el-dialog>
    <el-dialog v-model="deviceSwitchOpen" title="更换适配设备" width="min(620px,94vw)" :close-on-click-modal="false" data-benefit-device-switch><p class="dialog-intro">包内已有手机「{{ includedPhone?.name || draft.includedPhoneSkuId }}」。配件和服务将保留，并重新核对适配状态。</p><p class="muted">仅更换适配对象，会保留原手机；同时替换时，仅将原包内手机换成新选的具体 SKU。</p><template #footer><el-button @click="deviceSwitchOpen = false">取消</el-button><el-button @click="finishDeviceSwitch(false)" data-benefit-device-context-only>仅更换适配对象</el-button><el-button type="primary" :disabled="pendingDevice?.kind !== 'sku'" @click="finishDeviceSwitch(true)" data-benefit-device-replace-phone>同时替换包内手机</el-button></template></el-dialog>
    <el-dialog :model-value="leaveOpen" :title="leaveIntent === 'service' ? '保留服务输入？' : '保存这次组包编辑？'" width="min(560px,94vw)" :close-on-click-modal="false" @update:model-value="(value: boolean) => { if (!value) continueEditing() }" data-benefit-leave><p>{{ leaveIntent === 'service' ? '服务弹窗有未确认输入。可继续填写、明确放弃，或校验通过后加入包内清单。' : serviceDirty ? '服务弹窗还有未确认输入。“保存草稿并离开”将先校验并加入完整服务，再保存整包；不完整输入会保留并阻止离开。' : '当前输入尚未保存。可以先保存为草稿，再离开；也可以继续编辑或明确放弃。' }}</p><p v-if="error" class="issue-error leave-error">{{ error }}</p><template #footer><el-button @click="continueEditing">继续编辑</el-button><el-button @click="discardAndLeave">{{ leaveIntent === 'service' ? '放弃服务输入' : '放弃并离开' }}</el-button><el-button type="primary" :loading="leaving" @click="saveAndLeave">{{ leaveIntent === 'service' ? '加入包内清单' : '保存草稿并离开' }}</el-button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">
