const candidateMatches = computed(() => {
  const device = draft.value.device
  const result = device?.kind === 'sku' ? queryDeviceAccessories(store.data, device.skuId) : device?.kind === 'model' ? queryModelAccessories(store.data, device.host) : undefined
  return new Map([...(result?.sales || []), ...(result?.pending || []), ...(result?.excluded || []), ...(result?.unavailable || [])].filter(item => item.target.kind === 'sku').map(item => [item.target.id, item]))
